from pathlib import Path
import base64
import datetime
import shutil
import py_compile
import sys

ROOT = Path.cwd()

if not (ROOT / "backend" / "labtwin").exists():
    raise SystemExit(
        "Run this script from the LabTwin-AI project root."
    )

payload = {'backend/labtwin/models.py': '', 'backend/labtwin/memory_views.py': '', 'backend/labtwin/views.py': '', 'backend/labtwin/adaptive_views.py': '', 'frontend/src/App.jsx': ''}

timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
backup_root = ROOT / ("v2_backup_" + timestamp)
backup_root.mkdir(parents=True, exist_ok=True)

targets = {}

for relative_path, encoded_content in payload.items():
    target = ROOT / relative_path
    if not target.exists():
        raise SystemExit(
            f"Required file not found: {target}"
        )
    targets[relative_path] = target

print("Creating backups...")

for relative_path, target in targets.items():
    backup = backup_root / relative_path
    backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(target, backup)

print(f"Backup folder: {backup_root}")

try:
    for relative_path, target in targets.items():
        content = base64.b64decode(
            payload[relative_path]
        ).decode("utf-8")

        target.write_text(
            content,
            encoding="utf-8"
        )

        print(f"Updated: {relative_path}")

    for relative_path in [
        "backend/labtwin/models.py",
        "backend/labtwin/memory_views.py",
        "backend/labtwin/views.py",
        "backend/labtwin/adaptive_views.py",
    ]:
        py_compile.compile(
            str(ROOT / relative_path),
            doraise=True
        )

    print("")
    print("LABTWIN V2 FILE PATCH SUCCESS")
    print("Python syntax checks passed.")
    print("")
    print("Next run:")
    print("  python manage.py makemigrations labtwin")
    print("  python manage.py migrate")
    print("  python manage.py check")

except Exception as error:
    print("")
    print("PATCH FAILED:", error)
    print("Restoring backups...")

    for relative_path, target in targets.items():
        backup = backup_root / relative_path
        if backup.exists():
            shutil.copy2(
                backup,
                target
            )

    raise
